package com.islamicknowledge.platform.feature.hadith

internal val HADITHS: List<HadithItem> = listOf(
    HadithItem("hadith-niyyah", "সহীহুল বুখারী", 1, "إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى دُنْيَا يُصِيبُهَا أَوْ إِلَى امْرَأَةٍ يَنْكِحُهَا فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ", "নিশ্চয়ই সমস্ত কাজ নিয়তের ওপর নির্ভরশীল। আর প্রত্যেক ব্যক্তি যা নিয়ত করে কেবল তা-ই পায়। সুতরাং যার হিজরত দুনিয়া হাসিলের উদ্দেশ্যে কিংবা কোনো নারীকে বিয়ের উদ্দেশ্যে হবে, তার হিজরত সেই উদ্দেশ্যেই গণ্য হবে যার জন্য সে হিজরত করেছে।", "সহীহুল বুখারী: 1"),
    HadithItem("hadith-jibreel", "সহীহ মুসলিম", 8, "قَالَ: فَأَخْبِرْنِي عَنِ الإِحْسَانِ، قَالَ: «أَنْ تَعْبُدَ اللهَ كَأَنَّكَ تَرَاهُ، فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ»", "জিবরীল (আ.) বললেন: আমাকে ইহসান সম্পর্কে বলুন। রাসূলুল্লাহ ﷺ বললেন: \"ইহসান হলো—তুমি এমনভাবে আল্লাহর ইবাদত করবে যেন তুমি তাঁকে দেখছো; আর যদি তুমি তাঁকে দেখতে নাও পাও, তবে নিশ্চয় তিনি তোমাকে দেখছেন।\"", "সহীহ মুসলিম: 8"),
    HadithItem("hadith-brotherhood-love", "সহীহুল বুখারী", 13, "لاَ يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ", "তোমাদের কেউ ততক্ষণ পর্যন্ত প্রকৃত মুমিন হতে পারবে না, যতক্ষণ না সে নিজের ভাইয়ের জন্য তা-ই পছন্দ করবে যা সে নিজের জন্য পছন্দ করে।", "সহীহুল বুখারী: 13"),
    HadithItem("hadith-good-character-scale", "জামে আত-তিরমিযী", 2002, "مَا مِنْ شَيْءٍ أَثْقَلُ فِي مِيزَانِ الْمُؤْمِنِ يَوْمَ الْقِيَامَةِ مِنْ حُسْنِ الْخُلُقِ، وَإِنَّ اللَّهَ لَيُبْغِضُ الْفَاحِشَ الْبَذِيءَ", "কিয়ামতের দিন মুমিনের দাঁড়িপাল্লায় উত্তম চরিত্রের চেয়ে ভারী আর কোনো জিনিস হবে না। আর নিশ্চয়ই আল্লাহ তাআলা অশ্লীল ও কটুভাষীকে চরম ঘৃণা করেন।", "জামে আত-তিরমিযী: 2002"),
    HadithItem("hadith-anger-control", "সহীহুল বুখারী", 6114, "لَيْسَ الشَّدِيدُ بِالصُّرَعَةِ، إِنَّمَا الشَّدِيدُ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ", "কুস্তিতে যে অপরকে ধরাশায়ী করে সে প্রকৃত বীর নয়; বরং প্রকৃতপক্ষে শক্তিশালী সেই ব্যক্তি, যে রাগের সময় নিজেকে নিয়ন্ত্রণে রাখতে পারে।", "সহীহুল বুখারী: 6114"),
    HadithItem("hadith-seeking-knowledge", "সহীহ মুসলিম", 2699, "مَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا، سَهَّلَ اللَّهُ لَهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ", "যে ব্যক্তি দ্বীনি জ্ঞানার্জনের জন্য কোনো পথ অবলম্বন করে, আল্লাহ তাআলা তার কারণে জান্নাতের পথ তার জন্য সহজ করে দেন।", "সহীহ মুসলিম: 2699"),
    HadithItem("hadith-learn-teach-quran", "সহীহুল বুখারী", 5027, "خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ", "তোমাদের মধ্যে সর্বোত্তম ব্যক্তি সেই, যে নিজে কুরআন শেখে এবং অন্যকে তা শেখায়।", "সহীহুল বুখারী: 5027"),
    HadithItem("hadith-tawbah-joy", "সহীহ মুসলিম", 2747, "لَلَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ عَبْدِهِ حِينَ يَتُوبُ إِلَيْهِ، مِنْ أَحَدِكُمْ كَانَ عَلَى رَاحِلَتِهِ بِأَرْضِ فَلاَةٍ، فَانْفَلَتَتْ مِنْهُ وَعَلَيْهَا طَعَامُهُ وَشَرَابُهُ", "বান্দা যখন আল্লাহর কাছে তওবা করে, তখন আল্লাহ তাআলা সেই ব্যক্তির চেয়েও বেশি আনন্দিত হন, যে কোনো জনমানবহীন মরুভূমিতে খাদ্য ও পানীয়সহ বাহন হারিয়ে ফেলার পর নিরাশ হয়ে মরার জন্য শুয়ে পড়েছিল, অতঃপর হঠাৎ চোখ মেলে তার বাহনটি তার সামনে অক্ষত দেখতে পায়!", "সহীহ মুসলিম: 2747"),
    HadithItem("hadith-adam-children-err", "জামে আত-তিরমিযী", 2499, "كُلُّ ابْنِ آدَمَ خَطَّاءٌ، وَخَيْرُ الْخَطَّائِينَ التَّوَّابُونَ", "আদম সন্তানের প্রত্যেকেই ভুলকারী বা অপরাধী; আর ভুলকারীদের মধ্যে সর্বোত্তম হলো তারা, যারা তওবা করে ফিরে আসে।", "জামে আত-তিরমিযী: 2499"),
    HadithItem("hadith-parents-mother", "সহীহুল বুখারী", 5971, "جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ﷺ فَقَالَ: يَا رَسُولَ اللَّهِ، مَنْ أَحَقُّ النَّاسِ بِحُسْنِ صَحَابَتِي؟ قَالَ: «أُمُّكَ»، قَالَ: ثُمَّ مَنْ؟ قَالَ: «ثُمَّ أُمُّكَ»، قَالَ: ثُمَّ مَنْ؟ قَالَ: «ثُمَّ أُمُّكَ»، قَالَ: ثُمَّ مَنْ؟ قَالَ: «ثُمَّ أَبُوكَ»", "এক ব্যক্তি রাসূলুল্লাহ ﷺ-এর কাছে এসে জিজ্ঞেস করল: \"হে আল্লাহর রাসূল! আমার সর্বোত্তম সদাচরণ পাওয়ার সবচেয়ে বেশি হকদার কে?\" তিনি বললেন: \"তোমার মা।\" লোকটি বলল: \"তারপর কে?\" তিনি বললেন: \"তোমার মা।\" লোকটি বলল: \"তারপর কে?\" তিনি বললেন: \"তোমার মা।\" লোকটি বলল: \"তারপর কে?\" তিনি বললেন: \"তারপর তোমার বাবা।\"", "সহীহুল বুখারী: 5971"),
    HadithItem("hadith-silatur-rahim-rizq", "সহীহুল বুখারী", 2067, "مَنْ أَحَبَّ أَنْ يُبْسَطَ لَهُ فِي رِزْقِهِ، وَيُنْسَأَ لَهُ فِي أَثَرِهِ، فَلْيَصِلْ رَحِمَهُ", "যে ব্যক্তি তার রিজিকে প্রাচুর্য ও বরকত পেতে চায় এবং তার হায়াত দীর্ঘ হোক তা পছন্দ করে, সে যেন আত্মীয়তার বন্ধন অটুট রাখে (সিলাতুর রাহিম)।", "সহীহুল বুখারী: 2067"),
    HadithItem("hadith-honest-merchant", "জামে আত-তিরমিযী", 1209, "التَّاجِرُ الصَّدُوقُ الأَمِينُ مَعَ النَّبِيِّينَ، وَالصِّدِّيقِينَ، وَالشُّهَدَاءِ", "সত্যবাদী ও বিশ্বস্ত আমানতদার ব্যবসায়ী কিয়ামতের দিন নবীগণ, সিদ্দীকগণ এবং শহীদগণের সাথে থাকবেন।", "জামে আত-তিরমিযী: 1209"),
    HadithItem("hadith-halal-haram-clear", "সহীহুল বুখারী", 52, "إِنَّ الحَلاَلَ بَيِّنٌ، وَإِنَّ الحَرَامَ بَيِّنٌ، وَبَيْنَهُمَا مُشْتَبِهَاتٌ لاَ يَعْلَمُهُنَّ كَثِيرٌ مِنَ النَّاسِ، فَمَنِ اتَّقَى الشُّبُهَاتِ اسْتَبْرَأَ لِدِينِهِ وَعِرْضِهِ... أَلاَ وَإِنَّ فِي الجَسَدِ مُضْغَةً، إِذَا صَلَحَتْ صَلَحَ الجَسَدُ كُلُّهُ، وَإِذَا فَسَدَتْ فَسَدَ الجَسَدُ كُلُّهُ، أَلاَ وَهِيَ القَلْبُ", "নিশ্চয়ই হালাল স্পষ্ট এবং হারামও স্পষ্ট। আর এ দুটির মাঝে রয়েছে বহু সন্দেহজনক বিষয়, যা অনেক মানুষ জানে না। যে ব্যক্তি সন্দেহজনক বিষয় থেকে বেঁচে থাকল, সে নিজের দ্বীন ও আত্মসম্মানকে নিষ্কলুষ রাখল... জেনে রেখো! শরীরের মধ্যে একটি গোশতের টুকরো রয়েছে; তা যদি সুস্থ ও ভালো থাকে তবে পুরো শরীরটাই ভালো থাকে, আর তা যদি নষ্ট হয়ে যায় তবে পুরো শরীরটাই নষ্ট হয়ে যায়। জেনে রেখো! সেই টুকরোটি হলো কলব (অন্তর)।", "সহীহুল বুখারী: 52"),
    HadithItem("hadith-relieving-distress", "সহীহ মুসলিম", 2699, "مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا، نَفَّسَ اللَّهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ، وَمَنْ يَسَّرَ عَلَى مُعْسِرٍ، يَسَّرَ اللَّهُ عَلَيْهِ فِي الدُّنْيَا وَالآخِرَةِ، وَمَنْ سَتَرَ مُسْلِمًا، سَتَرَهُ اللَّهُ فِي الدُّنْيَا وَالآخِرَةِ، وَاللَّهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ", "যে ব্যক্তি কোনো মুমিনের পার্থিব কোনো কষ্ট লাঘব করে দেবে, আল্লাহ কিয়ামতের দিন তার একটি বড় বিপদ দূর করে দেবেন। যে ব্যক্তি কোনো অভাবগ্রস্তের সংকট সহজ করবে, আল্লাহ দুনিয়া ও আখিরাতে তার সবকিছু সহজ করে দেবেন। আর যে ব্যক্তি কোনো মুসলিমের দোষত্রুটি ঢেকে রাখবে, আল্লাহ দুনিয়া ও আখিরাতে তার দোষত্রুটি গোপন রাখবেন। বান্দা যতক্ষণ পর্যন্ত তার ভাইয়ের সাহায্যে নিয়োজিত থাকে, আল্লাহ ততক্ষণ পর্যন্ত সেই বান্দার সাহায্যে থাকেন।", "সহীহ মুসলিম: 2699"),
    HadithItem("hadith-leaving-useless", "জামে আত-তিরমিযী", 2317, "مِنْ حُسْنِ إِسْلاَمِ المَرْءِ تَرْكُهُ مَا لاَ يَعْنِيهِ", "মানুষের ইসলামের অন্যতম সৌন্দর্য হলো—তার জন্য যা অনর্থক ও অপ্রয়োজনীয় (যার সাথে দ্বীন বা দুনিয়ার কোনো কল্যাণ নেই), তা বর্জন করা।", "জামে আত-তিরমিযী: 2317"),
    HadithItem("hadith-smiling-charity", "জামে আত-তিরমিযী", 1956, "تَبَسُّمُكَ فِي وَجْهِ أَخِيكَ لَكَ صَدَقَةٌ", "তোমার মুসলিম ভাইয়ের মুখের দিকে তাকিয়ে তোমার একটু মুচকি হাসি দেওয়াও একটি সদকা (পুণ্যের কাজ)।", "জামে আত-তিরমিযী: 1956")
)
